import{_ as n,o as a,c as i,ai as e}from"./chunks/framework.BxxKhjs3.js";const t="/pub-blog/assets/image-20240614060533270.BJMKxYAo.png",l="/pub-blog/assets/image-20240614062827544.DRM5qOeO.png",p="/pub-blog/assets/image-20240614063056447.BwNcMlON.png",r="/pub-blog/assets/image-20240614063405194.C0fpWh5L.png",h="/pub-blog/assets/image-20240614063637583.CguPAI6A.png",o="/pub-blog/assets/image-20240614063803815.Rp-omSWo.png",k="/pub-blog/assets/image-20240614064037096.liHa9FNE.png",_=JSON.parse('{"title":"HarmonyOS Next 设计模式-单例模式","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 设计模式-单例模式/HarmonyOS Next 设计模式-单例模式.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 设计模式-单例模式/HarmonyOS Next 设计模式-单例模式.md","lastUpdated":1730788610000,"__rawMarkdown":"# HarmonyOS Next 设计模式-单例模式\\n\\n## 前言\\n\\n软件设计模式（[Design pattern](https://baike.baidu.com/item/Design pattern/10186718?fromModule=lemma_inlink)），又称设计模式，是一套被反复使用、多数人知晓的、经过分类编目的、[代码设计](https://baike.baidu.com/item/代码设计/5499787?fromModule=lemma_inlink)经验的总结。使用设计模式是为了可重用代码、让代码更容易被他人理解、保证代码可靠性、程序的重用性。\\n\\n**设计模式的作用是：为我们在进行稍微复杂的程序设计时，迅速提高可靠的解决方案。而不是等待问题暴露了，再去修复我们的程序**\\n\\n\\n\\n## 小故事\\n\\n1991年，Erich Gamma 与Richard Helm, Ralph Johnson ,John Vlissides合作出版了**Design Patterns - Elements of Reusable Object-Oriented Software** 一书，在此书中共收录了23个设计模式\\n\\n- **创建型模式，共五种：工厂方法模式、抽象工厂模式、单例模式、建造者模式、原型模式。**\\n- **结构型模式，共七种：适配器模式、装饰器模式、代理模式、外观模式、桥接模式、组合模式、享元模式。**\\n- **行为型模式，共十一种：策略模式、模板方法模式、观察者模式、迭代子模式、责任链模式、命令模式、备忘录模式、状态模式、访问者模式、中介者模式、解释器模式。**\\n\\n在实际开发中，很少会有程序员在同一个项目中全部用上以上的23种设计模式。所以边学边用、学以致用即可。\\n\\n## 单例模式\\n\\n> 单例模式(Singleton)，保证一个类仅有一个实例，并提供一个访问它的全局访问点。\\n\\n好比如在一个规模不大的公司中，存在以下的角色\\n\\n1. 人事\\n2. 财务\\n3. 开发\\n4. 测试\\n5. 实施\\n6. 运维\\n7. 网管\\n8. 老板\\n\\n**但其实由始至终，都只是你一个人在充当以上的角色而已。**\\n\\n\\n\\n## 使用场景\\n\\n太多了\\n\\n1. **系统服务管理**：鸿蒙操作系统中有很多系统服务，如系统时间管理、网络管理等。这些服务需要全局唯一的实例来提供服务，以确保服务的唯一性和一致性。通过使用单例模式，可以确保系统中只有一个这样的服务实例，方便管理和访问。\\n2. **设备访问**：鸿蒙操作系统中的设备访问层，如摄像头访问、传感器访问等，也需要使用单例模式来确保只有一个实例进行设备访问。这有助于避免多个实例同时访问设备导致的冲突和资源浪费。\\n3. **资源管理**：鸿蒙操作系统中的资源管理器，如内存管理器、文件系统管理器等，也需要使用单例模式来管理全局资源。通过单例模式，可以确保只有一个实例对资源进行管理和分配，提高系统的稳定性和性能。\\n4. **全局状态管理**：在鸿蒙应用开发中，经常需要全局唯一的实例来管理整个应用的配置和状态，如数据库访问对象等。通过使用单例模式，可以保证整个应用只有一个实例，避免重复实例造成的资源浪费和数据不一致。\\n\\n## 程序设计\\n\\n进入正题，众所周知，每当我们new一个实例的时候，内存中都会开辟一个新的空间，此时不同的实例是存在各自的内存空间中的。\\n\\n![image-20240614060533270](readme.assets/image-20240614060533270.png)\\n\\n---\\n\\n对应内存示意图为：\\n\\n![image-20240614062827544](readme.assets/image-20240614062827544.png)\\n\\n## 改造版本1\\n\\n因为new天生的特性就会开辟新内存空间，因此我们改造的方向是不让用户通过new来创建实例。替换成静态方法的方式来创建\\n\\n![image-20240614063056447](readme.assets/image-20240614063056447.png)\\n\\n核心代码在于 **static getInstance** 这里，它用过判断是否已经存在实例来决定是否要执行new操作\\n\\n![image-20240614063405194](readme.assets/image-20240614063405194.png)\\n\\n对比结果：\\n\\n![image-20240614063637583](readme.assets/image-20240614063637583.png)\\n\\n## 改造版本2\\n\\n但是这个时候可能会有小伙伴忘记我们使用了单例模式了，它还是一样会通过new的方式创建对象\\n\\n![image-20240614063803815](readme.assets/image-20240614063803815.png)\\n\\n此时我们可以将 **constructor** 设置为 私有，这样当小伙伴**new**的时候，便会有一个语法错误提示\\n\\n![image-20240614064037096](readme.assets/image-20240614064037096.png)\\n\\n> ps: artTs中 不能 使用 new.target 来判断用户是否存在new的行为\\n\\n## 完整代码\\n\\n```ts\\nclass Person {\\n  static instance: Person | null = null\\n\\n  static getInstance() {\\n    if (!Person.instance) {\\n      Person.instance = new Person()\\n    }\\n    return Person.instance\\n  }\\n\\n    // 设置方法为私有\\n    private  constructor() {   \\n  }\\n}\\n\\nconst p1 = Person.getInstance()\\nconst p2 = Person.getInstance()\\nconsole.log(\\"\\", p1 === p2)// true\\n\\n```\\n\\n"}'),g={name:"鸿蒙开发技巧/HarmonyOS Next 设计模式-单例模式/HarmonyOS Next 设计模式-单例模式.md"};function c(m,s,d,E,b,u){return a(),i("div",null,[...s[0]||(s[0]=[e("",37)])])}const F=n(g,[["render",c]]);export{_ as __pageData,F as default};
